import{_ as d,o as e,c as a,a2 as o}from"./chunks/framework.CvydjLy7.js";const p=JSON.parse('{"title":"一、官方 IO 一章覆盖了什么","description":"","frontmatter":{"title":"一、官方 IO 一章覆盖了什么"},"headers":[{"level":3,"title":"1.1 本篇在案例工程里加了什么","slug":"_1-1-本篇在案例工程里加了什么","link":"#_1-1-本篇在案例工程里加了什么","children":[]}],"relativePath":"ch07/01.md","filePath":"ch07/01.md","lastUpdated":1789497795000}'),r={name:"ch07/01.md"};function c(i,t,n,l,h,s){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="一、官方-io-一章覆盖了什么" tabindex="-1">一、官方 IO 一章覆盖了什么 <a class="header-anchor" href="#一、官方-io-一章覆盖了什么" aria-label="Permalink to &quot;一、官方 IO 一章覆盖了什么&quot;">​</a></h1><p>官方的 IO 章节标题是 &quot;IO&quot;，字面看像是文件读写，实际是个杂物间，收的都是“应用与外部活动交互”的技术：</p><table tabindex="0"><thead><tr><th>官方小节</th><th>讲什么</th><th>本篇处理方式</th></tr></thead><tbody><tr><td>缓存</td><td><code>@Cacheable</code> 抽象、八种缓存实现</td><td>第二节，含实测</td></tr><tr><td>校验</td><td>Bean Validation、方法级校验</td><td>第三节，含实测</td></tr><tr><td>REST Client</td><td><code>RestClient</code>、<code>RestTemplate</code>、底层 HTTP 库</td><td>第四节，含实测</td></tr><tr><td>邮件</td><td><code>JavaMailSender</code></td><td>第七节，只讲配置要点</td></tr><tr><td>Quartz</td><td>需要持久化的定时任务</td><td>第八节，只讲与 <code>@Scheduled</code> 的分工</td></tr><tr><td>Batch / gRPC / Web Services / JMS</td><td>各技术栈集成的入口</td><td>提及不展开</td></tr></tbody></table><p>任务调度不在 IO 章下，而是放在 Features 章，本篇第六节一并讲完——它和缓存有很自然的配合场景。</p><h3 id="_1-1-本篇在案例工程里加了什么" tabindex="-1">1.1 本篇在案例工程里加了什么 <a class="header-anchor" href="#_1-1-本篇在案例工程里加了什么" aria-label="Permalink to &quot;1.1 本篇在案例工程里加了什么&quot;">​</a></h3><p>第 6 篇结束时 <code>activity-server</code> 有 42 个测试。本篇新增的代码集中在下面六个文件：</p><table tabindex="0"><thead><tr><th>新增文件</th><th>作用</th></tr></thead><tbody><tr><td><code>config/CacheConfig.java</code></td><td>只挂一个 <code>@EnableCaching</code></td></tr><tr><td><code>config/RestClientConfig.java</code></td><td>构建调用外部目录服务的 <code>RestClient</code></td></tr><tr><td><code>config/ExternalApiProperties.java</code></td><td>外部服务的地址与超时配置，带启动期校验</td></tr><tr><td><code>config/SchedulingConfig.java</code></td><td>只挂一个 <code>@EnableScheduling</code></td></tr><tr><td><code>service/ExternalCatalogService.java</code></td><td>调用外部接口，演示三类失败的处理</td></tr><tr><td><code>service/CacheWarmupJob.java</code></td><td>定时清理场地缓存</td></tr></tbody></table><p>最终测试数从 42 增加到 <strong>58</strong>，全部通过。</p>',8)])])}const b=d(r,[["render",c]]);export{p as __pageData,b as default};
